package echo

import (
	"fmt"
	"net/http"
	"testing"
)

func TestZZFuzzPanic(t *testing.T) {
	patterns := []string{
		"/", "/a", "/a/b", "/a/b/c", "/a/b/c/d",
		"/:p", "/:p/b", "/:p/b/c", "/:p/:q", "/:p/:q/c", "/:p/:q/:r",
		"/*", "/a/*", "/a/b/*", "/:p/*", "/a/:p/*", "/:p/:q/*",
		"/a/:p", "/a/:p/c", "/a/b/:p", "/a/:p/:q",
	}
	paths := []string{
		"", "/", "//", "///", "/a", "/a/", "/a/b", "/a/b/", "/a/b/c", "/a/b/c/", "/a/b/c/d", "/a/b/c/d/e",
		"/x", "/x/", "/x/y", "/x/y/", "/x/y/z", "/x/y/z/w",
		"a", "a/b", "*", "/*", "/a/*", "/:p", "/a/b/c/d/e/f",
	}
	for _, p1 := range patterns {
		for _, p2 := range patterns {
			for _, p3 := range patterns {
				func() {
					defer func() {
						if r := recover(); r != nil {
							t.Errorf("PANIC routes=[%q %q %q] : %v", p1, p2, p3, r)
						}
					}()
					e := New()
					r := e.router
					r.Add(http.MethodGet, p1, func(c Context) error { return nil })
					r.Add(http.MethodGet, p2, func(c Context) error { return nil })
					r.Add(http.MethodGet, p3, func(c Context) error { return nil })
					for _, p := range paths {
						func() {
							defer func() {
								if rec := recover(); rec != nil {
									t.Errorf("PANIC routes=[%q %q %q] path=%q : %v", p1, p2, p3, p, rec)
								}
							}()
							c := e.NewContext(nil, nil).(*context)
							r.Find(http.MethodGet, p, c)
							_ = c.handler
						}()
					}
				}()
			}
		}
	}
	fmt.Println("done")
}
EOF
