package echo

import (
	"math/rand"
	"net/http"
	"strings"
	"testing"
)

func randPattern(rnd *rand.Rand) string {
	n := 1 + rnd.Intn(4)
	var sb strings.Builder
	for i := 0; i < n; i++ {
		switch rnd.Intn(4) {
		case 0:
			sb.WriteString("/" + string(rune('a'+rnd.Intn(3))))
		case 1:
			sb.WriteString("/:" + string(rune('a'+rnd.Intn(3))))
		case 2:
			sb.WriteString("/*")
		case 3:
			sb.WriteString("/")
		}
	}
	return sb.String()
}

func randPath(rnd *rand.Rand) string {
	n := rnd.Intn(5)
	var sb strings.Builder
	for i := 0; i < n; i++ {
		sb.WriteString("/" + string(rune('a'+rnd.Intn(4))))
	}
	if rnd.Intn(4) == 0 {
		sb.WriteString("/")
	}
	return sb.String()
}

func TestZZFuzzRandom(t *testing.T) {
	rnd := rand.New(rand.NewSource(42))
	for iter := 0; iter < 30000; iter++ {
		nRoutes := 1 + rnd.Intn(4)
		e := New()
		r := e.router
		pats := make([]string, 0, nRoutes)
		for i := 0; i < nRoutes; i++ {
			p := randPattern(rnd)
			pats = append(pats, p)
			func() {
				defer func() {
					if rec := recover(); rec != nil {
						t.Fatalf("PANIC in Add(%q) after %v: %v", p, pats, rec)
					}
				}()
				r.Add(http.MethodGet, p, func(c Context) error { return nil })
			}()
		}
		for i := 0; i < 6; i++ {
			p := randPath(rnd)
			if rnd.Intn(10) == 0 && len(p) > 0 {
				p = p[1:] // no leading slash
			}
			func() {
				defer func() {
					if rec := recover(); rec != nil {
						t.Fatalf("PANIC routes=%v Find(%q): %v", pats, p, rec)
					}
				}()
				c := e.NewContext(nil, nil).(*context)
				r.Find(http.MethodGet, p, c)
			}()
		}
	}
}
