// reference matcher following echo route syntax: static chars, :param (>=1 char up to next '/'), * (rest, may be empty)
func refMatch(pattern, path string) bool {
	i, j := 0, 0
	for i < len(pattern) {
		switch pattern[i] {
		case ':':
			for i < len(pattern) && pattern[i] != '/' {
				i++
			}
			start := j
			for j < len(path) && path[j] != '/' {
				j++
			}
			if j == start {
				return false
			}
		case '*':
			return true
		default:
			if j >= len(path) || path[j] != pattern[i] {
				return false
			}
			i++
			j++
		}
	}
	return j == len(path)
}

func randPattern2(rnd *rand.Rand) string {
	n := 1 + rnd.Intn(4)
	var sb strings.Builder
	for i := 0; i < n; i++ {
		switch rnd.Intn(5) {
		case 0:
			sb.WriteString("/" + string(rune('a'+rnd.Intn(3))))
		case 1:
			sb.WriteString("/:" + string(rune('a'+rnd.Intn(3))))
		case 2:
			if i == n-1 {
				sb.WriteString("/*")
			} else {
				sb.WriteString("/" + string(rune('a'+rnd.Intn(3))))
			}
		case 3:
			sb.WriteString("/")
		case 4:
			sb.WriteString(string(rune('a' + rnd.Intn(3))))
		}
	}
	return sb.String()
}

func randPath2(rnd *rand.Rand) string {
	n := rnd.Intn(5)
	var sb strings.Builder
	for i := 0; i < n; i++ {
		sb.WriteString("/" + string(rune('a'+rnd.Intn(4))))
	}
	if rnd.Intn(4) == 0 {
		sb.WriteString("/")
	}
	return sb.String()
}

